let profileUser=null;
async function loadUserProfile(){if(!profileUser)return;const key=`${profileUser.agent_id}/${profileUser.user_id}`;const memories=(await api('/api/user-profile?agent_id='+encodeURIComponent(profileUser.agent_id)+'&user_id='+profileUser.user_id))||[];if(!profileUser||key!==`${profileUser.agent_id}/${profileUser.user_id}`)return;const list=$('user-profile-memory');list.replaceChildren();if(!memories.length){empty(list,'No remembered facts yet. They appear when this person explicitly asks the bot to remember something.');return}for(const m of memories){const row=element('div',undefined,'profile-memory-item');row.append(element('p',m.content),element('small',`${m.chat_title||'Chat '+m.chat_id} · ${fmtTime(m.created_at)}`));row.append(button('Forget',async()=>{if(!(await confirmAsync('Forget this saved fact?','It will be removed from this profile and from conversation memory. The source message stays in history.','Forget')))return;await api('/api/memory','DELETE',{agent_id:m.agent_id,bot_id:m.bot_id,chat_id:m.chat_id,thread_id:m.thread_id||0,source_message_id:m.source_message_id});notice('Saved fact removed.');await loadUserProfile()},'destructive-text quiet'));list.append(row)}}
