function renderMemoryFacts(scope,memories){const list=$('memory-facts');list.replaceChildren();if(!memories?.length){empty(list,'No saved facts in this conversation.');return}for(const m of memories){const row=element('div',undefined,'memory-fact');const content=element('p',m.content);const meta=element('small',`${memoryAuthor(m)} · ${fmtTime(m.created_at)} · source message ${m.source_message_id}`);const forget=button('Forget',async()=>{if(!(await confirmAsync('Forget this saved fact?','It will no longer be included in future model context. The source message stays in conversation history.','Forget')))return;await api('/api/memory','DELETE',{agent_id:scope.agent_id,bot_id:scope.bot_id,chat_id:scope.chat_id,thread_id:scope.thread_id||0,source_message_id:m.source_message_id});notice('Saved fact removed.');await loadMemory()},'destructive-text quiet');row.append(content,meta,forget);list.append(row)}}
async function loadMemory(){const key=$('memory-scope').value;const scope=(snapshot?.data.chats||[]).find(c=>scopeKey(c)===key);if(!scope){$('memory-summary').textContent='Choose a conversation to inspect its memory.';$('memory-checkpoint').textContent='No conversation selected';$('memory-pending').textContent='';empty($('memory-facts'),'No conversation selected.');return}const data=await api('/api/context?'+params(scope));const summary=data.Summary||{};$('memory-summary').textContent=summary.content||'No summary yet. Older messages are summarized automatically.';$('memory-checkpoint').textContent=summary.through_id?`Covers messages through ${summary.through_at?fmtTime(summary.through_at):'#'+summary.through_id}`:'No checkpoint yet';const pending=summary.pending_count||0;$('memory-pending').textContent=`${pending.toLocaleString()} recent message${pending===1?'':'s'} not summarized`;renderMemoryFacts(scope,data.ExplicitMemories||[])}
