let mcpSnapshot;
const splitList=value=>value.split(',').map(s=>s.trim()).filter(Boolean);
async function loadMCP(){mcpSnapshot=await api('/api/mcp?scope='+$('mcp-scope').value);$('mcp-reset').hidden=!mcpSnapshot.overridden;$('mcp-source').textContent=mcpSnapshot.overridden?'Database override · changes apply automatically.':'Inherited from configuration.';$('mcp-bot-hint').textContent='Available bot aliases: '+mcpSnapshot.bots.join(', ');const body=$('mcp-list');empty(body,'No integrations yet. Add a server when a bot needs external tools.',4);if(mcpSnapshot.servers.length)body.replaceChildren();for(const rowData of mcpSnapshot.servers){const d=rowData.definition,row=element('tr');const name=element('div',d.name);name.append(element('small',{http:'Streamable HTTP',sse:'SSE',stdio:'Local process'}[d.transport]||d.transport));cell(row,name);const access=element('div',`Bots: ${(d.bots||[]).join(', ')||'none'}`);access.append(element('small',`Tools: ${(d.tools||[]).join(', ')||'none'}`));cell(row,access);cell(row,badge(d.enabled?'Enabled':'Disabled',!d.enabled));cell(row,actionMenu('Integration actions',[{label:'Edit server',action:()=>editMCP(rowData)},{label:'Discover tools',action:async()=>{const result=await api('/api/mcp/probe','POST',{scope:mcpSnapshot.scope,name:d.name});$('mcp-discovery-wrap').hidden=false;$('mcp-discovery').textContent=(result.tools||[]).map(t=>t.function.description).join('\n\n')||'No tools advertised.';$('mcp-discovery-wrap').scrollIntoView({block:'nearest'})}},{label:'Remove server',danger:true,action:async()=>{if(await confirmAsync(`Remove ${d.name}?`,'Its tools will no longer be available to bots.','Remove')){await api('/api/mcp','DELETE',{scope:mcpSnapshot.scope,name:d.name,version:mcpSnapshot.version});notice('Server removed. Applying automatically…');await loadMCP()}}}]));body.append(row)}labelTables()}
$('mcp-discovery-close').onclick=()=>{$('mcp-discovery-wrap').hidden=true};
function mcpTransport(){const local=$('mcp-transport').value==='stdio';$('mcp-local').hidden=!local;$('mcp-remote').hidden=local;}
function editMCP(row){const d=row?.definition;$('mcp-form-title').textContent=d?'Edit MCP server':'Add MCP server';$('mcp-name').value=d?.name||'';$('mcp-name').readOnly=!!d;$('mcp-transport').value=d?.transport||'http';$('mcp-url').value=d?.url||'';$('mcp-command').value=d?.command||'';$('mcp-args').value=JSON.stringify(d?.args||[]);$('mcp-token').value='';$('mcp-clear-token').checked=false;$('mcp-env').value='';$('mcp-bots').value=(d?.bots||[]).join(', ');$('mcp-tools').value=(d?.tools||[]).join(', ');$('mcp-enabled').checked=d?.enabled||false;mcpTransport();sheet('mcp-sheet',true);(d?$('mcp-url'):$('mcp-name')).focus();}
