let appliedSettingsAt='';
async function runtimeStatus(){
 const state=await api('/api/runtime');
 const el=$('runtime-status');
 el.textContent=state.state==='error'?'Settings not applied: '+state.error:state.state==='applying'?'Applying settings…':'Settings applied · live updates';
 el.title=el.textContent;
 el.className=state.state==='error'?'error':state.state==='applying'?'applying':'';
 if(state.state==='applied'&&state.applied_at!==appliedSettingsAt&&!document.querySelector('#settings input:focus')){
  appliedSettingsAt=state.applied_at;
  if($('notice').textContent.includes('Applying'))notice('Settings applied.');
  if(!$('settings').hidden)await loadSettings();
 }
}
act(runtimeStatus)();setInterval(()=>{if(document.visibilityState==='visible')act(runtimeStatus)()},1000);

// Cursor navigation is independent for each list. Refresh preserves the selected page.
const listPages={};
async function fetchList(kind,move){
 const page=listPages[kind]||(listPages[kind]={cursor:'',stack:[],next:''});
 if(move==='next'&&page.next){page.stack.push(page.cursor);page.cursor=page.next}
 if(move==='previous'&&page.stack.length)page.cursor=page.stack.pop();
 if(move==='first'){page.cursor='';page.stack=[]}
 const q=new URLSearchParams({limit:50,cursor:page.cursor});
 const data=await api('/api/lists/'+kind+'?'+q);page.next=data.next_cursor;
 snapshot.data[kind]=data.items||[];
 return data;
}
function pager(kind,target){
 let box=$('pager-'+kind);if(!box){box=element('div',undefined,'pager');box.id='pager-'+kind;target.after(box)}
 box.replaceChildren();const p=listPages[kind];
 box.hidden=!p.next&&!p.stack.length;
 const prev=button('‹ Previous',async()=>{await fetchList(kind,'previous');renderPaged()});prev.disabled=!p.stack.length;
 const next=button('Next ›',async()=>{await fetchList(kind,'next');renderPaged()});next.disabled=!p.next;
 const first=button('First',async()=>{await fetchList(kind,'first');renderPaged()});first.disabled=!p.stack.length;
 box.append(first,prev,element('span','Page '+(p.stack.length+1)),next);
}
function renderTools(items){
 const body=$('tool-outcomes');empty(body,'No tool calls recorded.',4);if(items.length)body.replaceChildren();
 for(const item of items){const row=element('tr');row.dataset.uiKey=`tool/${item.job_id}/${item.step}`;const chat=(snapshot.data.chats||[]).find(c=>String(c.bot_id)===String(item.bot_id)&&String(c.chat_id)===String(item.chat_id));const scope=element('div',chat?.title||`Chat ${item.chat_id}`);scope.append(element('small',`Job ${item.job_id}`));cell(row,scope);let payload=item.request;try{if(typeof payload==='string')payload=JSON.parse(payload)}catch{}const toolName=payload?.function?.name||payload?.name||'Tool call';const request=element('div',toolName,'technical-cell');request.append(detailBlock('Request details',item.request));cell(row,request);const result=element('div',item.state==='completed'?'Completed':item.state==='uncertain'?'Outcome unknown':'In progress','technical-cell');if(item.result)result.append(detailBlock('Result details',item.result));cell(row,result);const actions=element('div',undefined,'actions');actions.append(badge(item.resolution||item.state,(!item.resolution&&item.state!=='completed')));if(!item.resolution&&['started','uncertain'].includes(item.state))actions.append(button('Resolve',()=>resolveOutcome(item,item.step)));cell(row,actions);body.append(row)}
}
let resolutionItem=null;
function resolveOutcome(item,target){
 resolutionItem={job_id:item.job_id,target,version:item.version};
 $('resolution-title').textContent=`Resolve job ${item.job_id} / ${target}`;
 $('resolution-action').value='dismiss';$('resolution-reason').value='';$('resolution-message').value='';$('resolution-time').value='';$('resolution-result').value='';$('resolution-ack').checked=false;resolutionFields();sheet('resolution-sheet',true);$('resolution-reason').focus();
}
function resolutionFields(){const confirm=$('resolution-action').value==='confirm';const delivery=resolutionItem?.target.startsWith('delivery:');$('resolution-delivery').hidden=!confirm||!delivery;$('resolution-tool').hidden=!confirm||delivery}
$('resolution-action').onchange=resolutionFields;
$('resolution-cancel').onclick=()=>sheet('resolution-sheet',false);
$('resolution-sheet').addEventListener('close',()=>{resolutionItem=null});
$('resolution-form').onsubmit=act(async()=>{
 if(!resolutionItem||!$('resolution-ack').checked)throw Error('Confirm that you checked the external outcome');
 const body={...resolutionItem,action:$('resolution-action').value,reason:$('resolution-reason').value};
 if(body.action==='confirm'&&body.target.startsWith('delivery:')){
  body.message_id=Number($('resolution-message').value);body.sent_at=Date.parse($('resolution-time').value);
  if(!Number.isSafeInteger(body.message_id)||body.message_id<=0||!Number.isFinite(body.sent_at))throw Error('A valid message ID and ISO send time with timezone are required');
 }else if(body.action==='confirm'){body.result=$('resolution-result').value;JSON.parse(body.result)}
 await api('/api/resolve-outcome','POST',body);sheet('resolution-sheet',false);notice('Resolution recorded. The uncertain operation will not be repeated.');await refresh();
});
function renderAudit(){const body=$('audit-list');const expanded=new Set(Array.from(body.querySelectorAll('details[open]')).map(e=>e.dataset.auditId));empty(body,'No administrative changes recorded yet.',3);if((snapshot.data.audit||[]).length)body.replaceChildren();for(const a of snapshot.data.audit||[]){const row=element('tr');const when=element('div',fmtTime(a.created_at));when.append(element('small',a.subject));cell(row,when);const label=String(a.operation||'Change').replaceAll('_',' ');const op=element('div',label.charAt(0).toUpperCase()+label.slice(1));op.append(badge(a.status<400?'Completed':`Failed · ${a.status}`,a.status>=400));cell(row,op);const details=element('details',undefined,'technical');details.dataset.auditId=String(a.id);details.open=expanded.has(String(a.id));const content=element('div',undefined,'audit-details');content.append(detailBlock('Request',a.request),detailBlock('Before',a.before_state),detailBlock('After',a.after_state));details.append(element('summary','Review details'),content);cell(row,details);body.append(row)}}
function labelTables(){document.querySelectorAll('table').forEach(table=>{const labels=Array.from(table.querySelectorAll('thead th')).map(th=>th.textContent.trim());table.querySelectorAll('tbody tr').forEach(row=>Array.from(row.cells).forEach((td,index)=>td.dataset.label=labels[index]||''))})}
function renderPaged(){render();renderAudit();pager('audit',$('audit-list').closest('.table-scroll'));renderTools(snapshot.data.tools||[]);pager('chats',$('chat-list'));pager('bots',$('demo-bot').closest('.form-group'));pager('tasks',$('task-list').closest('.table-scroll'));pager('users',$('user-list').closest('.table-scroll'));pager('deliveries',$('deliveries').closest('.table-scroll'));pager('tools',$('tool-outcomes').closest('.table-scroll'));labelTables()}

let historyCursor='',historyNext='',historyStack=[];
function renderHistoryPager(){
 let box=$('history-pager');if(!box){box=element('div',undefined,'pager');box.id='history-pager';$('history').after(box)}box.replaceChildren();
 box.hidden=!historyNext&&!historyStack.length;
 const older=button('‹ Older',async()=>{historyStack.push(historyCursor);historyCursor=historyNext;await loadContext()});older.disabled=!historyNext;
 const newer=button('Newer ›',async()=>{historyCursor=historyStack.pop()||'';await loadContext()});newer.disabled=!historyStack.length;
 box.append(older,newer);
}

async function loadStatus(){
 const data=await api('/api/status'),a=data.activity||{};
 const health=$('status-health');health.replaceChildren(element('span',undefined,'status-dot'),element('strong','Application ready'),element('span',`Database ${data.database} · checked ${fmtTime(data.generated_at)}`));
 const metrics=[['Bots',a.bots],['Conversations',a.chats],['People',a.users],['Messages',a.messages],['Remembered facts',a.remembered_facts],['Active tasks',a.active_tasks],['Uncertain sends',a.uncertain_deliveries],['Uncertain tools',a.uncertain_tools],['Last activity',a.last_activity_at?fmtTime(a.last_activity_at):'—']];
 const metricBox=$('status-metrics');metricBox.replaceChildren();for(const [label,value] of metrics){const item=element('div',undefined,'status-metric');item.append(element('strong',String(value??0)),element('span',label));metricBox.append(item)}
 const queue=$('status-queue');queue.replaceChildren();for(const item of a.queue||[])queue.append(badge(`${item.status}: ${item.count}`,item.status==='dead'||item.status==='retry'));if(!queue.children.length)queue.append(element('span','Queue is empty','empty-inline'));
 const caps=$('status-capabilities');caps.replaceChildren();for(const item of data.capabilities||[]){const row=element('div',undefined,'capability-row');row.append(element('strong',item.name),element('small',item.detail),badge(item.state,item.state==='off'||item.state==='conditional'));caps.append(row)}
 const profiles=$('status-profiles');profiles.replaceChildren();for(const p of data.runtime?.bot_profiles||[]){const card=element('article',undefined,'bot-profile-card');const head=element('div',undefined,'bot-profile-head');const identity=element('div');identity.append(element('strong',p.name||'Unnamed bot'),element('small',p.username?`@${p.username}`:`Bot ${p.bot_id}`));head.append(identity,badge(p.context_included?'In agent context':'Not in context',!p.context_included));const fields=element('dl',undefined,'bot-profile-fields');for(const [label,value] of [['Name',p.name],['Username',p.username?`@${p.username}`:''],['Bio',p.bio],['Description',p.description],['Avatar analysis',p.avatar_description||(p.avatar_present?'Avatar present; analysis unavailable.':'No avatar.')]]){fields.append(element('dt',label),element('dd',value||'Not set'))}card.append(head,fields,element('small',`Profile refreshed ${p.refreshed_at?fmtTime(p.refreshed_at):'—'}`,'bot-profile-refresh'));profiles.append(card)}if(!profiles.children.length)profiles.append(element('p','No active bot profiles.','empty'));
 const failures=$('status-failures');failures.replaceChildren();for(const item of a.recent_failures||[]){const row=element('div',undefined,'failure-row');row.append(element('strong',`${item.kind} · job ${item.id}`),element('time',item.updated_at?fmtTime(Number(item.updated_at)):''),element('small',`${item.agent_id} · bot ${item.bot_id} · chat ${item.chat_id} · ${item.attempts}/${item.max_attempts} attempts`));failures.append(row)}if(!failures.children.length)failures.append(element('p','No retired jobs.','empty'));
}

let selectedSkillName='';
function skillScope(){const [agent_id,bot]=($('skill-bot').value||'').split('/');return{agent_id,bot_id:Number(bot)}}
async function loadSkills(){
 if(!$('skills-files-panel').hidden){await loadVFS();return}
 const sc=skillScope(),list=$('skill-list');if(!sc.agent_id||!sc.bot_id){empty(list,'No bot is available.');return}
 const data=await api('/api/skills?'+new URLSearchParams(sc));list.replaceChildren();
 for(const skill of data.skills||[]){const item=button('',()=>selectSkill(skill.name),'capability-item');item.dataset.skillName=skill.name;item.classList.toggle('selected',skill.name===selectedSkillName);const head=element('span',undefined,'capability-item-head');head.append(element('strong',skill.name),badge(skill.status,skill.status!=='active'));item.append(head,element('small',skill.description),element('span',`Version ${skill.version} · ${fmtTime(skill.updated_at)}`,'capability-meta'));list.append(item)}
 if(!list.children.length){empty(list,'No skills yet. The agent can create one when it finds a reusable workflow.');selectedSkillName='';$('skill-source').textContent='The Starlark source will appear here.';return}
 const next=(data.skills||[]).find(s=>s.name===selectedSkillName)||(data.skills||[])[0];await selectSkill(next.name)
}
async function selectSkill(name){
 selectedSkillName=name;document.querySelectorAll('#skill-list [data-skill-name]').forEach(b=>b.classList.toggle('selected',b.dataset.skillName===name));const sc=skillScope();const data=await api('/api/skills?'+new URLSearchParams({...sc,name}));const versions=data.versions||[],latest=versions[0];if(!latest)return;
 const identity=$('skill-identity');identity.replaceChildren();const title=element('div');title.append(element('h2',latest.name),element('p',latest.description));identity.append(title,badge(latest.status,latest.status!=='active'));
 const strip=$('skill-versions');strip.replaceChildren();for(const version of versions){const chip=button(`v${version.version}`,()=>showSkillVersion(version),'version-chip'+(version.id===latest.id?' selected':''));chip.title=`${version.status} · ${fmtTime(version.updated_at)}`;strip.append(chip)}showSkillVersion(latest)
}
function showSkillVersion(version){document.querySelectorAll('#skill-versions button').forEach(b=>b.classList.toggle('selected',b.textContent===`v${version.version}`));$('skill-source').textContent=version.source;$('skill-test-output').textContent=version.error||version.test_output||'No test result.'}

function currentVFSScope(){return(snapshot.data.chats||[]).find(c=>scopeKey(c)===$('vfs-scope').value)}
function currentVFSUser(){const parts=($('vfs-user').value||'').split('/');return Number(parts[1]||0)}
async function loadVFS(){
 const sc=currentVFSScope(),namespace=$('vfs-namespace').value,list=$('vfs-list');$('vfs-user-row').hidden=namespace!=='user';if(!sc){empty(list,'Choose a conversation scope.');return}
 const q=new URLSearchParams({...Object.fromEntries(new URLSearchParams(params(sc))),namespace,prefix:'',user_id:namespace==='user'?currentVFSUser():0});const data=await api('/api/vfs?'+q);list.replaceChildren();
 for(const file of data.files||[]){const full=`/${namespace}/${file.path}`;const item=button('',()=>selectVFSFile(full),'capability-item file-item');item.append(element('strong',full),element('small',`${file.content.length.toLocaleString()} characters · v${file.version}`));list.append(item)}
 if(!list.children.length)empty(list,'No files in this namespace. Skills can create them during a successful run.');$('vfs-identity').replaceChildren(element('div',undefined));$('vfs-identity').firstChild.append(element('h2','Select a file'),element('p','Paths and contents are scoped to the selected context.'));$('vfs-content').textContent='File content will appear here.'
}
async function selectVFSFile(path){
 const sc=currentVFSScope(),namespace=$('vfs-namespace').value,q=new URLSearchParams({...Object.fromEntries(new URLSearchParams(params(sc))),path,user_id:namespace==='user'?currentVFSUser():0});const data=await api('/api/vfs?'+q),file=data.file;document.querySelectorAll('#vfs-list button').forEach(b=>b.classList.toggle('selected',b.querySelector('strong')?.textContent===path));const identity=$('vfs-identity');identity.replaceChildren();const title=element('div');title.append(element('h2',path),element('p',`${file.mime_type} · version ${file.version} · updated ${fmtTime(file.updated_at)}`));identity.append(title);$('vfs-content').textContent=file.content
}
function showSkillSection(files){$('skills-catalog-panel').hidden=files;$('skills-files-panel').hidden=!files;$('skills-catalog-tab').classList.toggle('selected',!files);$('skills-files-tab').classList.toggle('selected',files);act(files?loadVFS:loadSkills)()}
$('skills-catalog-tab').onclick=()=>showSkillSection(false);$('skills-files-tab').onclick=()=>showSkillSection(true);$('skill-bot').onchange=act(loadSkills);$('vfs-scope').onchange=act(loadVFS);$('vfs-namespace').onchange=act(loadVFS);$('vfs-user').onchange=act(loadVFS);

$('settings-scope').onchange=act(loadSettings);

$('mcp-scope').onchange=act(async()=>{sheet('mcp-sheet',false);await loadMCP()});
